{"cards": [{"node_code": "N_d67b327312aeed46", "definition": "研究汽车在行驶、转向、制动等工况下的受力平衡、运动方程及能量传递规律的学科，涵盖整车及关键部件的力学模型与动力学分析。", "boundary": "本节点聚焦于汽车运动的“基础力学机理”与“动力学方程”。边界在于区分“通用动力学分析”与“特定性能指标计算”：若内容旨在建立或求解汽车在复杂工况下的运动微分方程、受力分析，归本节点；若内容直接针对加速、制动距离等具体性能指标进行计算与评价，归对应的动力性、制动性等节点。", "includes": ["汽车行驶、转向、制动过程中的受力分析与运动方程", "整车及悬架、转向系统的动力学模型与仿真", "汽车在特殊路面或极端工况下的力学行为分析"], "excludes": ["具体性能指标（如最高车速、制动距离）的标准化计算与评价", "零部件的结构强度设计与材料疲劳分析"], "sibling_distinctions": [{"other_code": "N_0115d7a840896978", "rule": "本节点侧重建立描述汽车运动的通用力学模型与方程；动力性节点侧重基于模型计算加速、爬坡等具体性能指标。"}, {"other_code": "N_05252f00a346bf66", "rule": "本节点侧重制动过程中的力学平衡与运动学分析；制动性节点侧重制动距离、稳定性等性能指标的评价。"}], "cross_boundary_rule": "若内容涉及“基于动力学模型的制动性能预测”，主挂载本节点（因核心是动力学建模）；若仅涉及“制动距离计算”，主挂载汽车制动性。"}, {"node_code": "N_0115d7a840896978", "definition": "研究汽车加速能力、最高行驶速度、爬坡能力及加速时间等性能指标的理论计算、影响因素分析及优化方法的学科领域。", "boundary": "本节点聚焦于汽车“向前运动”的能力指标。边界在于区分“动力性”与“燃料经济性”：动力性关注“能跑多快、多有力”，经济性关注“跑同样距离耗多少能”。若内容涉及发动机功率匹配对加速的影响，归本节点；若涉及油耗计算，归燃料经济性。", "includes": ["汽车最高车速、加速时间、最大爬坡度等指标的理论计算", "发动机、传动系参数对动力性的影响分析", "汽车动力性匹配与优化设计理论"], "excludes": ["汽车制动性能分析", "汽车燃油消耗率及排放计算", "汽车操纵稳定性分析"], "sibling_distinctions": [{"other_code": "N_05252f00a346bf66", "rule": "动力性研究“加速与爬坡”能力，制动性研究“减速与停车”能力，二者运动方向相反。"}, {"other_code": "N_3aab23d0ae365d3a", "rule": "动力性关注“输出能力”（功率、扭矩），燃料经济性关注“能量效率”（油耗、电耗）。"}], "cross_boundary_rule": "若内容涉及“动力性与经济性的综合权衡”，主挂载汽车燃料经济性（因通常以经济性为约束优化动力性）或视具体侧重而定，若侧重动力参数计算则归动力性。"}, {"node_code": "N_05252f00a346bf66", "definition": "研究汽车制动过程中的力学特性、制动距离、制动稳定性及制动效能评价指标的理论计算与分析方法。", "boundary": "本节点聚焦于汽车“减速与停车”的性能指标。边界在于区分“制动性”与“操纵稳定性”：制动性侧重直线或特定工况下的减速能力与制动距离；操纵稳定性侧重转向过程中的轨迹保持与抗干扰能力。若内容涉及制动时的侧向稳定性，可关联操纵稳定性，但主挂载制动性。", "includes": ["制动距离、制动减速度、制动效能系数的理论计算", "制动过程中的轴荷转移与轮胎附着利用分析", "制动稳定性（如制动跑偏、侧滑）的理论分析"], "excludes": ["制动系统（制动器、管路）的具体结构设计与制造", "汽车加速与爬坡性能分析", "非制动工况下的操纵稳定性分析"], "sibling_distinctions": [{"other_code": "N_0115d7a840896978", "rule": "制动性研究“减速”过程，动力性研究“加速”过程。"}, {"other_code": "N_e2c6c5780e42807e", "rule": "制动性侧重“纵向减速”性能，操纵稳定性侧重“横向转向”性能，但制动时的横向稳定性常作为制动性的一部分。"}], "cross_boundary_rule": "若内容涉及“制动对操纵稳定性的影响”，主挂载汽车制动性（因制动是触发条件）；若涉及“转向过程中的稳定性”，主挂载汽车的操纵性和稳定性。"}]}
